"""Auto-generated WeChat action tasks (explicit classes).

Generated by scripts/bench/generate/generate_wechat_action_tasks_module.py

IMPORTANT:
- These tasks are discoverable under app='wechat_action_tasks' (TaskRegistry).
- They open target app 'wechat' in setup().
- Judge is STATE-based (route/apps state), not VLM.
"""

from __future__ import annotations

from typing import Any, ClassVar

from bench_env.task.base import BaseTask, BaseApp
from bench_env.task.judge import JudgeInput, StateComparator


class _WechatActionTaskBase(BaseTask):
    """Base for generated tasks; name starts with _ to hide from registry."""

    apps: ClassVar[list[str]] = []
    templates: ClassVar[list[str]] = []
    difficulty: ClassVar[str] = "L1"
    parameters: ClassVar[dict[str, dict[str, Any]]] = {}
    optimal_paths: ClassVar[list[list[Any]]] = []
    note: ClassVar[str] = ""

    _judge: ClassVar[dict[str, Any]] = {}

    async def setup(self, env: Any):  # type: ignore[override]
        await self._prepare(env)
        state = await env.get_state()
        if self.sampler:
            result = self.sampler.sample(state, task=self)
            for k, v in result.params.items():
                if k in self._user_params:
                    continue
                self.params[k] = v
        # Always open wechat
        await env.open_app("wechat", wait_stable=True)
        return await env.get_observation()

    def _app_init(self, input: JudgeInput) -> dict[str, Any]:
        return (input.apps_init or {}).get("wechat", {}) or {}

    def _app_curr(self, input: JudgeInput) -> dict[str, Any]:
        return (input.apps or {}).get("wechat", {}) or {}

    def _get(self, app_state: dict[str, Any], path: str) -> Any:
        return BaseApp.get_by_path(app_state, path, None)

    def _find_by_id(self, items: Any, id_field: str, wanted: str) -> dict[str, Any] | None:
        if not wanted or not isinstance(items, list):
            return None
        for x in items:
            if isinstance(x, dict) and str(x.get(id_field) or "") == str(wanted):
                return x
        return None

    def check_goals(self, input: JudgeInput) -> list[dict[str, Any]]:
        j = dict(self._judge or {})
        kind = str(j.get("kind") or "").strip()

        init_app = self._app_init(input)
        curr_app = self._app_curr(input)

        if kind == "toggle_chat_field":
            chat_id = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            field = str(j.get("field") or "")
            b = self._find_by_id(init_app.get("chats", []), "id", chat_id) or {}
            a = self._find_by_id(curr_app.get("chats", []), "id", chat_id) or {}
            before, after = b.get(field), a.get(field)
            return [{"field": f"chats[{chat_id}].{field}", "expected": "toggled", "actual": {"init": before, "curr": after}, "passed": before != after}]

        if kind == "set_chat_field":
            chat_id = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            field = str(j.get("field") or "")
            expected = j.get("expected")
            a = self._find_by_id(curr_app.get("chats", []), "id", chat_id) or {}
            actual = a.get(field)
            return [{"field": f"chats[{chat_id}].{field}", "expected": expected, "actual": actual, "passed": actual == expected}]

        if kind == "toggle_contact_field":
            wxid = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            field = str(j.get("field") or "")
            b = self._find_by_id(init_app.get("contacts", []), "wxid", wxid) or {}
            a = self._find_by_id(curr_app.get("contacts", []), "wxid", wxid) or {}
            before, after = b.get(field), a.get(field)
            return [{"field": f"contacts[{wxid}].{field}", "expected": "toggled", "actual": {"init": before, "curr": after}, "passed": before != after}]

        if kind == "set_contact_field":
            wxid = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            field = str(j.get("field") or "")
            expected = j.get("expected")
            a = self._find_by_id(curr_app.get("contacts", []), "wxid", wxid) or {}
            actual = a.get(field)
            return [{"field": f"contacts[{wxid}].{field}", "expected": expected, "actual": actual, "passed": actual == expected}]

        if kind == "toggle_discover_item_field":
            item_id = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            field = str(j.get("field") or "")
            before = self._get(init_app, f"settings.discover.{item_id}.{field}")
            after = self._get(curr_app, f"settings.discover.{item_id}.{field}")
            return [{"field": f"settings.discover[{item_id}].{field}", "expected": "toggled", "actual": {"init": before, "curr": after}, "passed": before != after}]

        if kind == "set_discover_item_field":
            item_id = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            field = str(j.get("field") or "")
            expected = j.get("expected")
            actual = self._get(curr_app, f"settings.discover.{item_id}.{field}")
            return [{"field": f"settings.discover[{item_id}].{field}", "expected": expected, "actual": actual, "passed": actual == expected}]

        if kind == "toggle_field":
            path = str(j.get("path") or "")
            before = self._get(init_app, path)
            after = self._get(curr_app, path)
            return [{"field": path, "expected": "toggled", "actual": {"init": before, "curr": after}, "passed": before != after}]

        if kind == "set_field":
            path = str(j.get("path") or "")
            expected = j.get("expected")
            actual = self._get(curr_app, path)
            return [{"field": path, "expected": expected, "actual": actual, "passed": actual == expected}]

        if kind == "multi_set":
            checks = j.get("checks") if isinstance(j.get("checks"), list) else []
            out = []
            for c in checks:
                if not isinstance(c, dict):
                    continue
                path = str(c.get("path") or "")
                expected = c.get("expected")
                actual = self._get(curr_app, path)
                out.append({"field": path, "expected": expected, "actual": actual, "passed": actual == expected})
            return out if out else [{"field": "multi_set", "expected": "non-empty", "actual": checks, "passed": False}]

        if kind == "remove_authorized_app":
            app_id = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            init_ids = {str(x.get("id")) for x in (init_app.get("authorizedApps") or []) if isinstance(x, dict)}
            curr_ids = {str(x.get("id")) for x in (curr_app.get("authorizedApps") or []) if isinstance(x, dict)}
            passed = (app_id in init_ids) and (app_id not in curr_ids)
            return [{"field": "authorizedApps", "expected": f"removed {app_id}", "actual": {"init": list(init_ids)[:5], "curr": list(curr_ids)[:5]}, "passed": passed}]

        if kind == "list_len_increased":
            path = str(j.get("path") or "")
            before = self._get(init_app, path) or []
            after = self._get(curr_app, path) or []
            passed = isinstance(before, list) and isinstance(after, list) and len(after) > len(before)
            return [{"field": path, "expected": "len increased", "actual": {"init": len(before) if isinstance(before, list) else None, "curr": len(after) if isinstance(after, list) else None}, "passed": passed}]

        if kind == "field_changed":
            path = str(j.get("path") or "")
            before = self._get(init_app, path)
            after = self._get(curr_app, path)
            return [{"field": path, "expected": "changed", "actual": {"init": before, "curr": after}, "passed": before != after}]

        if kind == "wechat_chat_pat":
            chat_id = str(getattr(self.p, str(j.get("id_param") or "id"), "") or "")
            b = self._find_by_id(init_app.get("chats", []), "id", chat_id) or {}
            a = self._find_by_id(curr_app.get("chats", []), "id", chat_id) or {}
            bm = b.get("messages") or []
            am = a.get("messages") or []
            # Success: messages increased and contains system message with '拍了拍'
            grew = isinstance(bm, list) and isinstance(am, list) and len(am) > len(bm)
            has_pat = any(isinstance(m, dict) and str(m.get("type")) == "system" and "拍了拍" in str(m.get("content") or "") for m in (am if isinstance(am, list) else []))
            return [{"field": f"chats[{chat_id}].messages", "expected": "new system pat message", "actual": {"grew": grew, "has_pat": has_pat}, "passed": bool(grew and has_pat)}]

        # Default: any wechat state diff
        diffs = StateComparator.diff_states(init_app if isinstance(init_app, dict) else {}, curr_app if isinstance(curr_app, dict) else {}, prefix="")
        return [{"field": "wechat.state_changed", "expected": "diffs>0", "actual": f"diffs={len(diffs)}", "passed": len(diffs) > 0}]

    def get_expected_changes(self, input: JudgeInput) -> list[str]:
        """Return fully-qualified expected change prefixes (apps.wechat.*)."""
        j = dict(self._judge or {})
        kind = str(j.get("kind") or "").strip()

        if kind in {"toggle_chat_field", "set_chat_field", "wechat_chat_pat"}:
            return ["apps.wechat.chats"]
        if kind in {"toggle_contact_field", "set_contact_field"}:
            return ["apps.wechat.contacts"]
        if kind in {"toggle_discover_item_field", "set_discover_item_field"}:
            return ["apps.wechat.settings.discover"]
        if kind in {"toggle_field", "set_field", "field_changed"}:
            path = str(j.get("path") or "").strip()
            return [f"apps.wechat.{path}" if path else "apps.wechat"]
        if kind == "multi_set":
            checks = j.get("checks") if isinstance(j.get("checks"), list) else []
            out: list[str] = []
            for c in checks:
                if not isinstance(c, dict):
                    continue
                p = str(c.get("path") or "").strip()
                if p:
                    out.append(f"apps.wechat.{p}")
            return out or ["apps.wechat.settings"]
        if kind == "remove_authorized_app":
            return ["apps.wechat.authorizedApps"]
        if kind == "list_len_increased":
            p = str(j.get("path") or "").strip()
            return [f"apps.wechat.{p}" if p else "apps.wechat"]
        if kind == "state_diff":
            prefix = str(j.get("prefix") or "").strip()
            return [f"apps.wechat.{prefix}" if prefix else "apps.wechat"]

        return ["apps.wechat"]




